CREATE TABLE "Farm" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "Pump" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "farmId" TEXT NOT NULL REFERENCES "Farm"("id") ON UPDATE CASCADE ON DELETE RESTRICT);
CREATE TABLE "PlantProfile" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "dryBelowPct" INTEGER NOT NULL CHECK ("dryBelowPct" BETWEEN 0 AND 100));
CREATE TABLE "Zone" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "pumpId" TEXT NOT NULL REFERENCES "Pump"("id") ON UPDATE CASCADE ON DELETE RESTRICT, "plantProfileId" TEXT NOT NULL REFERENCES "PlantProfile"("id") ON UPDATE CASCADE ON DELETE RESTRICT);
